{
  "findings": [
    {
      "check_id": "CKV_AWS_389",
      "title": "Ensure AWS Auto Scaling group launch configuration doesn't have public IP address assignment enabled",
      "resource": "aws_launch_configuration.levelup-launchconfig",
      "severity": "MEDIUM",
      "explanation": "The launch configuration has no explicit 'associate_public_ip_address' attribute set, which may lead to unintended public exposure of instances."
    },
    {
      "check_id": "AVD-AWS-0130",
      "title": "Launch configuration does not require IMDS access to require a token",
      "resource": "aws_launch_configuration.levelup-launchconfig",
      "severity": "HIGH",
      "explanation": "Instance metadata service can be interacted with freely, potentially allowing unauthorized access to instance metadata."
    }
  ],
  "patched_code": "resource \"aws_launch_configuration\" \"levelup-launchconfig\" {\n  name_prefix     = \"levelup-launchconfig\"\n  image_id        = lookup(var.AMIS, var.AWS_REGION)\n  instance_type   = \"t2.micro\"\n  key_name        = aws_key_pair.levelup_key.key_name\n  associate_public_ip_address = false\n  metadata_options {\n    http_tokens = \"required\"\n  }\n}",
  "fix_summary": "Added 'associate_public_ip_address = false' to prevent public IP assignment and included 'metadata_options' block with 'http_tokens = \"required\"' to enforce IMDSv2 token requirement."
}
